/** Every notification the daemon sends, with its payload. Within a connection they arrive in the order the daemon raised them. */
export interface Notifications {
	/** The whole brick list, whenever anything in it changes. */
	'bricks/changed': BrickList;
	/** A brick has a route again: after it was lost, and also when it is first connected. Subscriptions on it carry on. */
	'bricks/reconnected': BrickIdPayload;
	/** A pairing started, whoever asked for it. */
	'bricks/pairingStarted': BrickIdPayload;
	/** One step of a running pairing. */
	'bricks/pairingEvent': PairingEvent;
	/** A pairing ended. */
	'bricks/pairingDone': PairingResult;
	/** The brick paired one-sidedly and the cockpit repaired it. */
	'bricks/oneSidedRepair': OneSidedRepairNotice;
	/** A followed program's state changed. */
	'programs/stateChanged': ProgramStateChanged;
	/** New telemetry values for a subscription. */
	'telemetry/update': TelemetryUpdate;
	/** A followed daisy chain changed. */
	'chain/changed': ChainChanged;
	/** A setting changed. */
	'settings/changed': SettingChanged;
	/** The access mode changed. */
	'settings/accessModeChanged': AccessModeState;
	/** A question this client was asked is no longer open. */
	'question/withdrawn': QuestionWithdrawn;
	/** The brick a client shows changed: it showed another or none, or it left while showing one. Carries every client as daemon/status names it. */
	'daemon/showsChanged': ShowsChanged;
}

export type NotificationName = keyof Notifications;

/** The requests the daemon sends a client. */
export interface ClientRequests {
	/** The daemon asks a client with a person at it; a client without a person answers keep. */
	'question/ask': { params: Question; result: QuestionReply };
}

