/** Reads a stable-core string as a ClientKind; a value this version does not know reads as 'mcp'. */
export function readClientKind(value: string): ClientKind {
	return (['vscode', 'cli', 'mcp', 'addon'] as readonly string[]).includes(value) ? value as ClientKind : 'mcp';
}

/** Reads a stable-core string as a BuildKind; a value this version does not know reads as 'release'. */
export function readBuildKind(value: string): BuildKind {
	return (['release', 'development'] as readonly string[]).includes(value) ? value as BuildKind : 'release';
}

/** Reads a stable-core string as a DaemonMode; a value this version does not know reads as 'hardware'. */
export function readDaemonMode(value: string): DaemonMode {
	return (['hardware', 'replay'] as readonly string[]).includes(value) ? value as DaemonMode : 'hardware';
}

/** Reads a stable-core string as a DaemonState; a value this version does not know reads as 'serving'. */
export function readDaemonState(value: string): DaemonState {
	return (['serving', 'exiting'] as readonly string[]).includes(value) ? value as DaemonState : 'serving';
}

